meMeter(){const meterW=200;const meterH=10;ctx.fillStyle='.fillRect(10,height-30,meterW,meterH);ctx.fillStyle='lime';ctx.fillRect(10,height-30,volume*meterW,meterH);ctx.strokeStyle='black';ctx.strokeRect(10,height-30,meterW,meterH);}function getCarPos(dist){let d=dist%totalLength;for(const of segments){if(d>seg.len){d-=seg.len}else{const t=d/seg.len;return{x:seg.p1.x+seg.dx*t,y:seg.p1.y+seg.dy*t}}}return trackPoints[0];}function drawTrack(){ctx.fillStyle='darkgreen';ctx.fillRect(0,0,width,height);ctx.strokeStyle='white';ctxWidth=40;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(trackPoints[0].x,trackPoints[0].y);for(let i=1;i<trackPoints.length;i++)ctx.lineTo(trackPoints[i].x,trackPoints[i].y);ctx.stroke();ctx.strokeStyle='black';ctx.lineWidth=2;ctx.stroke();}function drawObstacles(){ctx.fillStyle='red';for(const o of obstacles){ctx.beginPath();ctx.arc(o.x,o.y,o.r,0,Math.PI*2);ctx.fill();}}function checkCollision(pos){for(const o of obstacles){const dx=pos.x-o.x;const dy=pos.y-o.y;const d=Math.hypot(dx,dy);if(d<o.r+10){carSpeed*=0.5;carDist=Math.max(0,carDist-20);return true}}return falsefunction updateLap(){if(carDist%totalLength<carSpeed){const now=performance.now();if(lapStartTime===0)lapStartTime=now;const lapTime=(now-lapStartTime)/1000;if(lapTime<bestLap)bestLap=lapTime;lapCount++;lapStartTime=now;if(lapCount>=maxLaps){gameRunning=false;celebrate()}}}function drawHUD(){ctx.fillStyle='white';ctx.font='16px sans-serif';ctx.fillText(`Lap: ${lapCount}/${maxLaps}`,10,20);if(bestLap!==Infinity)ctx.fillText(`Best Lap: ${bestLap.toFixed(2)}s`,10,40)}function celebrate(){let flashes=0;function flash(){ctx.clearRect(0,0,width,height);drawTrack();drawObstacles();ctx.fillStyle='yellow';ctx.font='48px sans-serif';ctx.textAlign='center';ctx.fillText('Race Complete!',width/2,height/2);flashes++;if(flashes<6)setTimeout(flash,400);}flash()}function gameLoop(ts){if(!lastTime)lastTime=ts;const delta=ts-lastTime;lastTime=ts;ctx.clearRect(0,0,width,height);drawTrack();drawObstacle